class ChatbotGUI:
    def __init__(self, root):
        self.root = root
        self.root.title("Chatbot")
        self.root.geometry("550x600")

        # Chat area
        self.chat_area = scrolledtext.ScrolledText(self.root, wrap=tk.WORD, width=60, height=25, font=("Arial", 12))
        self.chat_area.pack(padx=10, pady=10)
        self.chat_area.config(state="disabled")

        # Input area
        self.input_field = tk.Entry(self.root, width=50, font=("Arial", 12))
        self.input_field.pack(padx=10, pady=5)
        self.input_field.bind("<Return>", self.send_message)

        # Send button
        self.send_button = tk.Button(self.root, text="Send", font=("Arial", 12), command=self.send_message)
        self.send_button.pack(pady=5)

        # Tag configurations
        self.chat_area.tag_config("user_tag", foreground="red", font=("Arial", 12, "bold"))
        self.chat_area.tag_config("bot_tag", foreground="green", font=("Arial", 12, "italic"))

        # Background color
        self.root.configure(bg="#87CEEB")

        # Initial message
        self.display_message("Chatbot: Hello! How can I help you today? 🥳", sender="bot")

    def display_message(self, message, sender="bot"):
        self.chat_area.config(state="normal")

        # Apply correct tag based on sender
        if sender == "user":
            self.chat_area.insert(tk.END, message + "\n", "user_tag")
        else:
            self.chat_area.insert(tk.END, message + "\n", "bot_tag")

        self.chat_area.config(state="disabled")
        self.chat_area.see(tk.END)

    def send_message(self, event=None):
        user_input = self.input_field.get().strip()
        if user_input:
            # Display user message
            self.display_message(f"You: {user_input}", sender="user")

            # Predict and get chatbot response
            intents_list = predict_class(user_input)
            response = get_response(intents_list, intents)

            # Display bot response
            self.display_message(f"Chatbot: {response} 🥳", sender="bot")

            # Clear input field
            self.input_field.delete(0, tk.END)

# Run the app
if __name__ == "__main__":
    root = tk.Tk()
    app = ChatbotGUI(root)
    root.mainloop()
